  const modeField = isa.modeField;
  if (instruction.mode.opcode > maxValue(modeField)) {
    return {
      reason:
        `the ISA's opcode ${instruction.mode.opcode} for mode "${instruction.mode.id}"` +
        ` does not fit the ${describeField(modeField)}`,
    };
