        errors.push({
          line,
          text,
          reason: `"${LABEL_DIRECTIVE}" takes exactly one name, got ${fields.length - 1}`,
        });
        continue;
      }
      const name = fields[1] ?? '';
      if (!LABEL_NAME.test(name)) {
        errors.push({
          line,
          text,
          reason:
