            line,
            text,
            reason:
              `unknown code "${token}" for the "${field.id}" field` +
              ` (expected ${Object.keys(codes).join(', ')})`,
          });
          failed = true;
          break;
        }
        if (code > maxValue(field)) {
          errors.push({
            line,
            text,
            reason: `the ISA's code ${code} for "${token}" does not fit the ${describeField(field)}`,
