    // The no-throw contract covers the `isa` argument too: `insertField` would
    // throw on a value its field cannot hold, so the encoder checks first.
    const narrowed: Isa = {
      ...OVERTURE_ISA,
      modes: OVERTURE_ISA.modes.map((mode) =>
        mode.id === 'move'
